#include "gfx/atlas.h"

#include <citro3d.h>
#include <tex3ds.h>

#include "atlas_t3x.h"   // generated by tex3ds from gfx/atlas.t3s

static C3D_Tex s_tex;

bool atlasInit(void)
{
	// vram = true: 256 KB of the ~6 MB VRAM budget, and texture reads out of VRAM
	// are the cheap ones on this GPU. Measured: linear free went 30,936 -> 30,680 KB
	// when this was false, i.e. the atlas was sitting in FCRAM instead.
	Tex3DS_Texture t3x = Tex3DS_TextureImport(atlas_t3x, atlas_t3x_size, &s_tex, NULL, true);
	if (!t3x)
		return false;

	// The t3x descriptor only describes the layout; the pixels now live in the
	// C3D_Tex, so it can go straight away.
	Tex3DS_TextureFree(t3x);

	// Nearest on both filters, and no mipmaps: this is pixel art and the whole
	// look depends on the pixels staying square. Mipmaps would also need padding
	// far wider than 2px to stay bleed-free.
	C3D_TexSetFilter(&s_tex, GPU_NEAREST, GPU_NEAREST);
	C3D_TexSetWrap(&s_tex, GPU_CLAMP_TO_EDGE, GPU_CLAMP_TO_EDGE);
	C3D_TexBind(0, &s_tex);
	return true;
}

void atlasExit(void)
{
	C3D_TexDelete(&s_tex);
}

AtlasRect atlasTile(int tile)
{
	return atlasRect(tile);   // world/atlas_uv.h — shared with the mesher
}
